//! Lua/LÖVE: the LuaJIT FFI wrapper over the C ABI bridge, and the driver that records,
//! diffs and benchmarks functions by name. Lua has no types to read, so the driver records
//! actual values instead.

use std::fmt::Write as _;

use crate::bridge::Manifest;
use crate::lang::lua::{receiver, signature};

/// Minimal JSON support for the generated Lua code (LuaJIT has no JSON module).
pub const CODEC_LUA: &str = r#"
-- Generated by rust-anything. JSON codec for recorded cases and bridge calls.
local codec = {}

local function escape(s)
  return (s:gsub('[%z\1-\31\\"]', function(c)
    local codes = { ['"'] = '\\"', ['\\'] = '\\\\', ['\b'] = '\\b', ['\f'] = '\\f',
      ['\n'] = '\\n', ['\r'] = '\\r', ['\t'] = '\\t' }
    return codes[c] or string.format('\\u%04x', c:byte())
  end))
end

function codec.encode(v, level)
  level = level or 0
  if level > 100 then error('json too deep') end
  local t = type(v)
  if t == 'nil' then return 'null' end
  if t == 'boolean' then return tostring(v) end
  if t == 'number' then
    if v ~= v then return '{"$num":"NaN"}' end
    if v == math.huge then return '{"$num":"Infinity"}' end
    if v == -math.huge then return '{"$num":"-Infinity"}' end
    return string.format('%.17g', v)
  end
  if t == 'string' then return '"' .. escape(v) .. '"' end
  if t == 'table' then
    local parts = {}
    local is_array = true
    local n = 0
    for k in pairs(v) do
      if type(k) ~= 'number' then is_array = false end
      n = n + 1
    end
    if is_array and n == #v then
      for i = 1, #v do parts[i] = codec.encode(v[i], level + 1) end
      return '[' .. table.concat(parts, ',') .. ']'
    end
    for k, val in pairs(v) do
      parts[#parts + 1] = codec.encode(tostring(k), level + 1) .. ':' .. codec.encode(val, level + 1)
    end
    return '{' .. table.concat(parts, ',') .. '}'
  end
  return 'null'
end

local function parse_string(s, i)
  local out = {}
  i = i + 1
  while i <= #s do
    local c = s:sub(i, i)
    if c == '"' then return table.concat(out), i + 1 end
    if c == '\\' then
      local e = s:sub(i + 1, i + 1)
      local map = { n = '\n', r = '\r', t = '\t', b = '\b', f = '\f', ['"'] = '"', ['\\'] = '\\' }
      if map[e] then out[#out + 1] = map[e]; i = i + 2
      elseif e == 'u' then
        out[#out + 1] = string.char(tonumber(s:sub(i + 2, i + 5), 16) % 256)
        i = i + 6
      else out[#out + 1] = e; i = i + 2 end
    else out[#out + 1] = c; i = i + 1 end
  end
  error('unterminated json string')
end

local function skip(s, i)
  while i <= #s and s:sub(i, i):match('%s') do i = i + 1 end
  return i
end

function codec.decode(s)
  local function value(i)
    i = skip(s, i)
    local c = s:sub(i, i)
    if c == '"' then
      local str, next_i = parse_string(s, i)
      return str, next_i
    end
    if c == '{' then
      local obj = {}
      i = skip(s, i + 1)
      if s:sub(i, i) == '}' then return obj, i + 1 end
      while true do
        local key, ni = value(i)
        i = skip(s, ni)
        if s:sub(i, i) ~= ':' then error('expected colon') end
        local val
        val, i = value(i + 1)
        obj[key] = val
        i = skip(s, i)
        if s:sub(i, i) == ',' then i = i + 1
        elseif s:sub(i, i) == '}' then return obj, i + 1
        else error('expected comma or brace') end
      end
    end
    if c == '[' then
      local arr = {}
      i = skip(s, i + 1)
      if s:sub(i, i) == ']' then return arr, i + 1 end
      while true do
        local val
        val, i = value(i)
        arr[#arr + 1] = val
        i = skip(s, i)
        if s:sub(i, i) == ',' then i = i + 1
        elseif s:sub(i, i) == ']' then return arr, i + 1
        else error('expected comma or bracket') end
      end
    end
    local rest = s:sub(i)
    local num = rest:match('^%-?%d+%.?%d*[eE]?[-+]?%d*')
    if num and num ~= '' then return tonumber(num), i + #num end
    if rest:match('^true') then return true, i + 4 end
    if rest:match('^false') then return false, i + 5 end
    if rest:match('^null') then return nil, i + 4 end
    error('bad json at ' .. i .. ': ' .. s:sub(i, i + 20))
  end
  local v = value(1)
  return v
end

function codec.normalize(v)
  if type(v) ~= 'table' then return v end
  if v['$num'] == 'NaN' then return 0 / 0 end
  if v['$num'] == 'Infinity' then return math.huge end
  if v['$num'] == '-Infinity' then return -math.huge end
  if v['$num'] == '-0' then return -0.0 end
  for k, val in pairs(v) do v[k] = codec.normalize(val) end
  return v
end

return codec
"#;

/// The LuaJIT FFI wrapper: the original function names, each calling the Rust cdylib.
pub fn wrapper(m: &Manifest) -> Result<String, String> {
    let lib = m.lib_name();
    let mut out = format!(
        "-- The Rust port of `{}`, generated by rust-anything. Load in place of the original.\n\
         -- Set RUST_ANYTHING_LUA_LIB to the built cdylib when running on a different machine.\n\
         local ffi = require('ffi')\n\
         ffi.cdef[[ char *rust_anything_call(const char *name, const char *args);\n\
                    void rust_anything_free(char *ptr); ]]\n\
         local native = ffi.load(os.getenv('RUST_ANYTHING_LUA_LIB') or '{}_native.so')\n\
         local codec = require('rust_anything_codec')\n\n\
         local function invoke(name, ...)\n\
           local ptr = native.rust_anything_call(name, codec.encode({{...}}))\n\
           local raw = ffi.string(ptr)\n\
           native.rust_anything_free(ptr)\n\
           local answer = codec.decode(raw)\n\
           if answer.error then error(answer.error, 0) end\n\
           return codec.normalize(answer.ok)\n\
         end\n\n",
        m.unit, lib
    );
    let _ = writeln!(out, "local M = {{}}");
    for f in &m.exports {
        let (recv, name) = receiver(f);
        let params = signature(f);
        let args: Vec<String> = f.params.iter().map(|p| p.name.clone()).collect();
        let _ = writeln!(
            out,
            "function M.{name}({params}) return invoke('{key}', {args}) end -- {recv}",
            key = f.name,
            args = args.join(", ")
        );
    }
    let _ = writeln!(out, "\nreturn M\n");
    Ok(out)
}

/// `{ name: [receiver, method] }` for the driver.
pub fn targets(m: &Manifest) -> serde_json::Value {
    serde_json::Value::Object(
        m.exports
            .iter()
            .map(|f| {
                let (recv, name) = receiver(f);
                (f.name.clone(), serde_json::json!([recv, name, f.file]))
            })
            .collect(),
    )
}

pub fn driver() -> String {
    format!("{CODEC_LUA}\n{DRIVER_LUA}")
}

const DRIVER_LUA: &str = r#"
-- Generated by rust-anything: record/diff/bench driver for Lua and LÖVE.
local codec = require('rust_anything_codec')

local args = { ... }
local mode, targets_path, cases_path, out_path, min_ms = args[1], args[2], args[3], args[4], tonumber(args[5]) or 0

local function read_lines(path)
  local out = {}
  for line in io.lines(path) do
    if line ~= '' then out[#out + 1] = codec.decode(line) end
  end
  return out
end

local targets = codec.decode(io.open(targets_path):read('*a'))
local modules = {}
local function load_files(count, first)
  for i = first, count do
    local path = args[i]
    if path then
      local chunk = loadfile(path)
      if chunk then
        local ok, mod = pcall(chunk)
        if ok and type(mod) == 'table' then modules[path] = mod end
      end
    end
  end
end

local function resolve(t)
  local recv, name, file = t[1], t[2], t[3]
  if recv == '_G' and type(_G[name]) == 'function' then return _G[name] end
  local holder = modules[file] or _G[recv] or _G
  if type(holder) == 'table' and type(holder[name]) == 'function' then return holder[name] end
  if type(_G[name]) == 'function' then return _G[name] end
  return nil
end

local function call(c)
  local target = resolve(targets[c['fn']] or {})
  if not target then return { error = 'no such function: ' .. tostring(c['fn']) } end
  local decoded = {}
  for i, v in ipairs(c['args'] or {}) do decoded[i] = codec.normalize(v) end
  local ok, value = pcall(target, table.unpack(decoded, 1, #decoded))
  if ok then
    local encoded = codec.encode(value)
    return { ok = codec.decode(encoded) }
  end
  return { error = tostring(value) }
end

local function same(expected, got)
  if tostring(got.error or ''):find('Rust panic:', 1, true) then return false end
  if expected.error ~= nil then return got.error ~= nil and expected.error == got.error end
  return got.error == nil and codec.encode(expected.ok) == codec.encode(got.ok)
end

if mode == 'record' then
  local out = io.open(out_path, 'w')
  load_files(#args, 6)
  local progress = os.getenv('RUST_ANYTHING_PROGRESS')
  local index = 0
  for _, c in ipairs(read_lines(cases_path)) do
    local line = { ['fn'] = c['fn'], args = c['args'] }
    local result = call(c)
    if result.ok ~= nil then line.ok = result.ok end
    if result.error ~= nil then line.error = result.error end
    local encoded = codec.encode(line)
    if encoded ~= 'null' then out:write(encoded, '\n'); out:flush() end
    index = index + 1
    if progress then
      local p = io.open(progress, 'a')
      if p then p:write(index, '\n'); p:close() end
    end
  end
  out:close()
elseif mode == 'diff' then
  load_files(#args, 6)
  local summary = { total = 0, passed = 0, failed = 0, missing = {}, mismatches = {} }
  for _, c in ipairs(read_lines(cases_path)) do
    summary.total = summary.total + 1
    local got = call(c)
    local expected = { ok = c.ok, error = c.error }
    if same(expected, got) then
      summary.passed = summary.passed + 1
    else
      summary.failed = summary.failed + 1
      summary.mismatches[#summary.mismatches + 1] = {
        ['fn'] = c['fn'], args = c['args'], expected = expected, actual = got
      }
    end
  end
  io.open(out_path, 'w'):write(codec.encode(summary))
elseif mode == 'bench' then
  load_files(#args, 6)
  local groups = {}
  for _, c in ipairs(read_lines(cases_path)) do
    groups[c['fn']] = groups[c['fn']] or {}
    groups[c['fn']][#groups[c['fn']] + 1] = c
  end
  local result = {}
  for name, cases in pairs(groups) do
    local once = function()
      for _, c in ipairs(cases) do call(c) end
    end
    once()
    local passes, start = 0, os.clock()
    repeat
      once()
      passes = passes + 1
    until (os.clock() - start) * 1000 >= min_ms
    result[name] = {
      cases = #cases,
      ns = (os.clock() - start) * 1e9 / math.max(1, passes * #cases)
    }
  end
  io.open(out_path, 'w'):write(codec.encode(result))
end
"#;

/// `cargo_toml` and `lib_rs` come from the generic C ABI backend.
pub fn cargo_toml(m: &Manifest) -> String {
    crate::codegen_ffi::cargo_toml(m)
}

pub fn lib_rs(m: &Manifest, api: &crate::codegen::PortApi) -> String {
    crate::codegen_ffi::lib_rs(m, api)
}

pub fn camel(lib: &str) -> String {
    lib.split('_')
        .map(|part| {
            let mut c = part.chars();
            c.next()
                .map(|f| f.to_uppercase().chain(c).collect::<String>())
                .unwrap_or_default()
        })
        .collect()
}
